/// Returns the word translated to [langCode], or the original English word if no translation exists.
String translateWord(String englishWord, String langCode) {
  if (langCode == 'en') return englishWord;
  return wordTranslations[englishWord.toLowerCase()]?[langCode] ?? englishWord;
}
